// P-015 "sync stats show no silent truncation" census. [self-imposed under AUTO #970, WI-10003944]
// Read-only. For every text_chunks surface in the live registry, cross-tabs each eligible
// parent's text length against the length maxChunks windows can cover, and the parent's
// stored chunk count against maxChunks. Silent truncation would show as a long parent with
// fewer than maxChunks chunks (tail lost somewhere other than the cap), a parent stored above
// the cap, or a long parent with no chunks at all. Prints one CENSUS line per surface.
export {};
const base = 'file://~/papercupai-workspace/papercusp/packages/operator-core/lib/';
const { CHUNK_SURFACES } = await import(base + 'search/chunks/registry.ts');
const { getOrgPg } = await import('@papercusp/db-org');
const { sql } = getOrgPg();

const TEXT_SURFACES = ['plans', 'operator_turns', 'work_items', 'consult_questions'];
for (const s of CHUNK_SURFACES as Array<Record<string, any>>) {
  if (!TEXT_SURFACES.includes(s.surface)) continue;
  const { size, overlap } = s.splitter;
  const max = s.maxChunks as number;
  const covered = size + (max - 1) * (size - overlap);
  const cols = (s.parent.key as Array<string | { column: string }>).map((c) => (typeof c === 'string' ? c : c.column));
  const key = `ARRAY[${cols.map((c) => `p.${c}::text`).join(', ')}]`;
  const where = s.eligibleSql ? `WHERE ${s.eligibleSql}` : '';
  const [r] = await sql.unsafe(
    `WITH par AS (SELECT ${key} AS k, length(${s.textSql}) AS len FROM ${s.parent.table} p ${where}),
          ch AS (SELECT parent_key AS k, count(*)::int AS n FROM harness_shared.text_chunks WHERE surface = $1 GROUP BY parent_key)
     SELECT count(*)::int AS parents,
            count(*) FILTER (WHERE par.len > $2)::int AS over_covered,
            count(*) FILTER (WHERE par.len > $2 AND ch.n = $3)::int AS over_at_cap,
            count(*) FILTER (WHERE par.len > $2 AND ch.n < $3)::int AS over_below_cap,
            count(*) FILTER (WHERE par.len > $2 AND ch.n IS NULL)::int AS over_unchunked,
            count(*) FILTER (WHERE ch.n > $3)::int AS above_cap,
            count(*) FILTER (WHERE ch.n = $3 AND par.len <= $2)::int AS at_cap_within_covered,
            max(ch.n)::int AS max_stored
       FROM par LEFT JOIN ch ON ch.k = par.k`,
    [s.surface, covered, max],
  );
  console.log('CENSUS', JSON.stringify({ surface: s.surface, maxChunks: max, coveredChars: covered, ...r }));
}
console.log('AT', new Date().toISOString());
await sql.end({ timeout: 5 });
